-- REM-A4-PROGRAMS-2 (2026-10-26, charter pillar autonomy; session rem-a4 fork F5): corrections to the dated notes of migrations/2026-10-26-rem-a4-programs.sql (merged before the check of its
-- own sentences finished) and the notes the first file did not write.
-- Corrections, each measured 2026-10-26 19:40Z in qnfo-audit:
--   100294 note: it said "PRs 4736, 4740 and 4746 landed three of them, 1000429 to 1000433 queued". PR 4736 is BREACH-DOCTOR-WATCHMAKER-1 (issue 1000398, a different family). In the BREACH-DOCTOR-1 family the code of 1000427 (PR 4746),
--     1000428 (PR 4740) and 1000430 (code task ct_im1000430c, merged 17:55Z) is merged; 1000429, 1000431 and 1000433 wait for qnfo-fleet-control/worker.js, held by the code loop.
--   100293 note: "63 of 103 merged tasks ... 40 waited longer" counted tasks with no recorded PR open time; of the 95 merged tasks of the last 7 days that have one, 63 opened their PR inside the first hour and 32 waited longer.
--     "35 failed and 4 NO-PROGRESS-CEILING-1" means 35 failed tasks, 4 of them NO-PROGRESS-CEILING-1. The claims "(a) handled by CONFLICT-REPAIR-DOER-1" and "(e) the breach doctor and the RED-DRAIN dispatch give every issue a doer path" were not measured
--     here and are withdrawn; the orchestrator already runs 8 lanes (TICK_LANES) and serialises tasks on one file, which is the measured source of the long waits.
--   100318 contract action: "12 on qnfo-ai" were 12 merged, 8 of them verified by the canary (qnfo-gateway: 7 merged, 7 verified).
-- New notes: 100279 (the time gate), 100318 and 100366 (the open parts), 2008 (the clear date of its 14-day window).
-- 2008: the last code task whose merge_note or last_error says "required check(s) failed" was created 2026-10-25T09:30:45Z (ct_zlm7wlfxfdnrxx, gate=failure); 33 such tasks since 2026-10-18, the latest five failing the gate job, which stopped being a
--   required check on 2026-10-26 (MERGE-STREAMLINE-1). With no new such task the 14-day window of the probe clears at 2026-11-08T09:31Z. The replacement lever (scripts/code-task-publish.py runs scripts/deploy_gate.py --check) is not shipped: --check
--   fetches and runs wrangler through npx for a real deploy --dry-run bundle build (a network fetch and tens of seconds on every publish, and a new way for the publisher to fail), a cost this session did not take on.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE remediation_contracts SET action = replace(action, '12 merged (8 verified) on qnfo-ai in 7 days', '12 on qnfo-ai in 7 days') WHERE class = 'issue-100318'

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS-2 correction 2026-10-26 (session rem-a4): in the BREACH-DOCTOR-1 family the code of 1000427 (PR 4746), 1000428 (PR 4740) and 1000430 (code task ct_im1000430c) is merged and those issues wait for their live measurement; 1000429, 1000431 and 1000433 wait for qnfo-fleet-control/worker.js, held by the code loop. PR 4736 belongs to BREACH-DOCTOR-WATCHMAKER-1 (1000398), a different family. This replaces the doer sentence for that family in the note above.'
 WHERE id = 100294 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS-2 correction') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS-2 correction 2026-10-26 (session rem-a4): of the 95 merged tasks of the last 7 days that have a recorded PR open time, 63 opened their PR inside the first hour and 32 waited longer (the note above counted 103 and 40). The 4 NO-PROGRESS-CEILING-1 failures are among the 35 failed tasks. The statements that part (a) is handled by CONFLICT-REPAIR-DOER-1 and part (e) by the breach doctor and the RED-DRAIN dispatch were not measured and are withdrawn. The orchestrator already runs 8 lanes (TICK_LANES = 8) and serialises tasks on one file, so the wait before the PR opens is the held-file and red-main queue; the two ways to shorten it are a claim hand-off between tasks on one file and fewer sessions holding qnfo-fleet-control/worker.js.'
 WHERE id = 100293 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS-2 correction') = 0;

UPDATE remediation_contracts SET action = replace(action, '7 verified loop merges on qnfo-gateway and 12 on qnfo-ai in 7 days', '7 verified loop merges on qnfo-gateway and 12 merged (8 verified) on qnfo-ai in 7 days')
 WHERE class = 'issue-100318' AND instr(action, '12 on qnfo-ai in 7 days') > 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS-2 2026-10-26 (session rem-a4): the lever landed 2026-10-20T04:00Z (transformation_levers tp=1 n=23 verified, code task ct_tt5zi4uqs43isc, PR 3198) and 36 code tasks on the loop-canaried workers have merged since 2026-10-19 with merge_state verified (14 on qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard and qnfo-code-orchestrator). The one CONTROL-PLANE-REVERTED-1 issue in the window (1000171, 2026-10-25T10:11Z) names push 7a9d293 of qnfo-gateway and no code task carries that sha: a canary race on a session push (the canary wanted 3.31.2 and saw the later 3.31.3). The contract on class issue-100279 now reads ok only 7 days after the lever landed (earliest 2026-10-27T04:00Z) with no loop merge reverted and no revert issue naming a code-task push; before that it reads a reason. One earlier loop merge ended revert-failed on 2026-10-19T18:55Z, outside the window.'
 WHERE id = 100279 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS-2 2026-10-26') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS-2 2026-10-26 (session rem-a4): measured. qnfo-ai and qnfo-gateway are already in PLAN_LOOP_CANARIED (qnfo-code-orchestrator), so PLAN_DENY_WORKERS no longer holds them; the code loop merged 12 tasks on qnfo-ai (8 verified by the canary) and 7 on qnfo-gateway (7 verified) in the last 7 days, so the lever''s third definition-of-done item (a code-loop PR on qnfo-gateway merged by the runner) holds. Still open: the two other lists (EVOLVE_DENY and TP_CONTROL_PLANE in qnfo-fleet-control) and the staged path itself: scripts/cf_ops_actions.py only reads worker-history (percentage per version); nothing uploads a version, routes a fraction, probes and promotes or rolls back without the changed worker, and deployment_history holds 224 plain deploy rows and no staged row for the two workers. The three parts: (1) cf-ops actions for a versioned deploy at a percentage, a promote and a rollback that each write a deployment_history row (action staged-deploy, staged-promote, staged-rollback); the action list also needs its input choice in .github/workflows/cf-ops-actions.yml, which the code loop''s merge scope denies, so a session or the stale-PR lane carries it; (2) a probe-and-promote workflow with the rollback; (3) after one promote and one rollback of each worker, remove qnfo-ai and qnfo-gateway from EVOLVE_DENY and TP_CONTROL_PLANE in one change (fold-guard.test.mjs keeps the lists equal). The contract on class issue-100318 reads the four staged rows, the lever status and the gateway merge, and says which is missing.'
 WHERE id = 100318 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS-2 2026-10-26') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS-2 2026-10-26 (session rem-a4): the definition of done (requests on workers with no public route under 3,000 a day) had no metric behind it; the contract on class issue-100366 now reads a reason until metric_registry holds worker_requests_nonpublic_per_day under 3000 and the lever row tp=2 n=3 is landed. The first part is the producer: a daily sum of workersInvocationsAdaptive requests over the live workers with no public route, from the Cloudflare analytics GraphQL API on a runner (qnfo-ops carries a cf_analytics reader; scripts/cf_ops_actions.py carries graphql() and d1x() helpers but no invocations query), registered in metric_registry together with its trigger or a named exemption (METRIC-CLOSED-LOOP-1). The second part is the one-pass probe in qnfo-fleet-control (worker_live_audit read by the dashboard, lifecycle and deploy-guard), a multi-worker change that is not a one-anchor edit and waits for the producer.'
 WHERE id = 100366 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS-2 2026-10-26') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = COALESCE(description, '') || char(10) ||
  'REM-A4-PROGRAMS-2 2026-10-26 (session rem-a4): re-measured. Its probe reads "defect: a code-loop pull request failed a required check in the last 14 days". The last code task whose merge_note or last_error says "required check(s) failed" was created 2026-10-25T09:30:45Z (ct_zlm7wlfxfdnrxx, gate=failure); 33 such tasks since 2026-10-18, the latest five failing the gate job, which stopped being a required check on 2026-10-26 (MERGE-STREAMLINE-1). With no new task of that kind the window clears at 2026-11-08T09:31Z and the probe then reads ok. The replacement lever (scripts/code-task-publish.py runs scripts/deploy_gate.py --check before it pushes) is not shipped: --check fetches and runs wrangler through npx for a real deploy --dry-run bundle build (a network fetch and tens of seconds on every publish, and a new way for the publisher to fail), and the 14-day definition of done is time-gated either way. The probe is unchanged.'
 WHERE id = 2008 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A4-PROGRAMS-2 2026-10-26') = 0;

